<template><view class="page"><view class="header"><view class="title">个人经营中心</view><view class="sub">所有指标只统计本人或下单时归属到本人的业务</view></view><view class="range"><picker mode="date" :value="startDate" @change="e=>startDate=e.detail.value"><view>{{startDate||'开始日期'}}</view></picker><text>至</text><picker mode="date" :value="endDate" @change="e=>endDate=e.detail.value"><view>{{endDate||'结束日期'}}</view></picker><button size="mini" @click="load">查询</button></view><view class="grid"><view v-for="item in cards" :key="item.key" class="card"><view class="label">{{item.label}}</view><view class="value">{{format(data[item.key])}}</view></view></view><view class="note">零售完成额按订单完成统计，普通退款和调拨退回均在实际发生日扣减；调拨按确认收货入库统计，历史区域和团队归属以业务发生时快照为准。</view></view></template>
<script>import{getJkPersonalReport}from'@/api/jk.js';export default{data(){return{startDate:'',endDate:'',data:{},cards:[{key:'retailPerformanceAmount',label:'零售完成额'},{key:'retailRefundAmount',label:'当期零售退款'},{key:'retailNetPerformanceAmount',label:'零售净业绩'},{key:'retailOrderCount',label:'归属订单数'},{key:'transferInboundAmount',label:'调拨入库额'},{key:'transferReturnAmount',label:'调拨退回额'},{key:'stockAvailableQty',label:'可用库存'},{key:'stockFrozenQty',label:'冻结库存'},{key:'pendingCommissionAmount',label:'待结算佣金'},{key:'settledCommissionAmount',label:'已结算佣金'},{key:'availableFundAmount',label:'可提现资金'},{key:'withdrawingAmount',label:'提现中'},{key:'withdrawnAmount',label:'已提现'}]}},onLoad(){this.load()},methods:{format(v){return v===undefined||v===null?'0':v},load(){uni.showLoading({title:'加载中'});getJkPersonalReport({startDate:this.startDate,endDate:this.endDate}).then(r=>this.data=(r&&r.data)||r||{}).finally(()=>uni.hideLoading())}}}</script>
<style scoped>.page{min-height:100vh;background:#f6f7f9;padding:24rpx}.header{padding:30rpx;background:linear-gradient(135deg,#18b997,#3b82f6);border-radius:20rpx;color:#fff}.title{font-size:36rpx;font-weight:600}.sub{font-size:24rpx;opacity:.85;margin-top:12rpx}.range{display:flex;align-items:center;gap:16rpx;background:#fff;padding:20rpx;margin-top:20rpx;border-radius:16rpx}.range picker{flex:1;color:#555}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18rpx;margin-top:20rpx}.card{background:#fff;border-radius:16rpx;padding:24rpx}.label{font-size:24rpx;color:#8a8f99}.value{font-size:36rpx;font-weight:600;margin-top:12rpx;color:#1f2937}.note{margin-top:20rpx;padding:22rpx;background:#fff7e6;color:#8a5a00;border-radius:16rpx;font-size:24rpx;line-height:1.6}</style>
